.ds-artifact-card {
  background: #ffffff;
  border: 1px solid var(--arxiv-border-light);
  border-radius: 6px;
  font-family: var(--arxiv-font-sans);
  overflow: hidden; /* clips list hover fills and the show-all button to the card radius */
}

/* ── Card heading ────────────────────────────────────────────────────── */

.ds-artifact-card-heading {
  margin: 0;
  padding: 10px 16px 9px;
  font-family: var(--arxiv-font-condensed);
  font-weight: 600;
  font-size: 0.6875rem; /* 11px — matches accordion dt and popover title */
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--arxiv-grey);
  border-bottom: 1px solid var(--arxiv-border-light);
}

/* ── Artifact list ───────────────────────────────────────────────────── */

.ds-artifact-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ds-artifact-row {
  border-bottom: 1px solid var(--arxiv-border-light);
}

.ds-artifact-row:last-child {
  border-bottom: none;
}

/* ── Block link (the entire row is the interactive target) ───────────── */

.ds-artifact-row-link {
  display: grid;
  /* min-width 0 on each column allows text-overflow:ellipsis to fire;
     without it, grid items don't shrink below their min-content size. */
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 3fr);
  align-items: baseline;
  gap: 4px 14px;
  padding: 10px 16px;
  color: var(--arxiv-ink);  /* override default anchor blue on label/platform */
  text-decoration: none;
  transition: background 0.10s;
}

.ds-artifact-row-link:hover {
  background: var(--arxiv-card-grey);
}

.ds-artifact-row-link:focus-visible {
  outline: 2px solid var(--arxiv-focus-ring);
  outline-offset: -2px; /* ring sits inside the card, doesn't bleed outside */
  border-radius: 4px;
}

/* ── Cell contents ───────────────────────────────────────────────────── */

.ds-artifact-type {
  font-size: 0.875rem; /* 14px */
  font-weight: 500;
  color: var(--arxiv-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-artifact-platform {
  font-size: 0.8125rem; /* 13px */
  color: var(--arxiv-grey);
  white-space: nowrap;
}

.ds-artifact-url-cell {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  font-size: 0.8125rem; /* 13px */
  color: var(--arxiv-link-blue);
  text-decoration: underline;
  text-underline-offset: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-artifact-row-link:hover .ds-artifact-url-cell {
  color: var(--arxiv-link-hover);
}

.ds-artifact-row-link:focus-visible .ds-artifact-url-cell {
  color: var(--arxiv-link-hover);
}

.ds-artifact-row-link:visited .ds-artifact-url-cell {
  color: var(--arxiv-link-visited);
}

/* External link icon (↗). aria-hidden in markup; .is-sr-only text carries
   the off-site meaning to screen readers.  */
.ds-artifact-ext-icon {
  flex-shrink: 0;
  width: 12px;
  height: 12px;
  stroke: currentColor;
  fill: none;
  opacity: 0.75;
  /* optical baseline nudge — SVG sits slightly low relative to text */
  margin-bottom: -1px;
}

/* ── Disclosure button (.ds-artifact-show-all) ───────────────────────
   Injected by JS when the card has >5 artifacts; not present in the
   static HTML. hidden attribute is removed by JS after injection.
   aria-expanded tracks collapsed/expanded state.
   Without JS: not present → all rows visible (progressive enhancement). */

.ds-artifact-show-all {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 9px 16px;
  background: none;
  border: none;
  border-top: 1px solid var(--arxiv-border-light);
  cursor: pointer;
  font-family: var(--arxiv-font-sans);
  font-size: 0.8125rem; /* 13px */
  font-weight: 500;
  color: var(--arxiv-link-blue);
  text-align: left;
  transition: background 0.10s, color 0.10s;
}

.ds-artifact-show-all:hover {
  background: var(--arxiv-card-grey);
  color: var(--arxiv-link-hover);
}

.ds-artifact-show-all:focus-visible {
  outline: 2px solid var(--arxiv-focus-ring);
  outline-offset: -2px;
}

.ds-artifact-show-all[hidden] { display: none; }

/* ── Narrow viewport (≤520px) ────────────────────────────────────────
   Switch from the 3-column grid to a wrapping flex layout:
   artifact type on its own full-width line; platform and URL share
   the second line. No information is hidden — the platform name
   drops to the second line rather than being truncated. */

@media (max-width: 520px) {
  .ds-artifact-row-link {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 2px 8px;
  }
  .ds-artifact-type {
    flex: 0 0 100%;   /* own line */
    white-space: normal;
  }
  .ds-artifact-platform {
    flex: 0 0 auto;
  }
  .ds-artifact-url-cell {
    flex: 1;
    min-width: 0;
  }
}

/* Forced colors — high-contrast OS mode. The icon follows system text
   color automatically; pin the URL to LinkText so it stays a link.
   Never set forced-color-adjust: none. */
@media (forced-colors: active) {
  .ds-artifact-card { border-color: ButtonBorder; }
  .ds-artifact-url-cell { color: LinkText; text-decoration-color: LinkText; }
  .ds-artifact-show-all { color: LinkText; }
}

@media (prefers-reduced-motion: reduce) {
  .ds-artifact-row-link,
  .ds-artifact-show-all { transition: none; }
}

